 parseAI=raw=>{let value=raw;if(value?.choices){value=value.choices[0]?.message?.content;if(Array.isArray(value))value=value.map(x=>x.text||'').join('')}if(typeof value!=='string')return value;const text=value.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{return JSON.parse(text)}catch{const start=text.indexOf('{'),end=text.lastIndexOf('}');if(start<0||end<=start)throw Error('AI 没有返回有效结构化结果');return JSON.parse(text.slice(start,end+1))}},
